import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import ComparePage from './ComparePage';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, addNotification, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(true);
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [updateStatus, setUpdateStatus] = useState(null);

  // ================= ЗАГРУЗКА ДАННЫХ ПОЛЬЗОВАТЕЛЯ =================
  const fetchData = useCallback(async () => {
    try {
      const [pRes, tRes, lRes] = await Promise.all([
        api.get('/purchases/my').catch(() => ({ data: [] })),
        api.get('/testdrives/my').catch(() => ({ data: [] })),
        api.get('/loans/my').catch(() => ({ data: [] })),
      ]);
      setPurchases(pRes.data);
      setTestDrives(tRes.data);
      setLoans(lRes.data);
    } catch (err) {
      console.error("Ошибка при получении данных личного кабинета:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
    // Инициализация избранного из localStorage
    const savedFavs = JSON.parse(localStorage.getItem(`favs_${user?.id}`) || '[]');
    setFavorites(savedFavs);
  }, [fetchData, user?.id]);

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setUpdateStatus(null);
    try {
      const res = await api.put('/auth/profile', profileForm);
      setUser(res.data);
      setUpdateStatus({ type: 'success', text: 'Профиль успешно обновлен!' });
    } catch (err) {
      setUpdateStatus({ type: 'error', text: 'Не удалось обновить профиль.' });
    }
  };

  const removeFavorite = (id) => {
    const updated = favorites.filter(c => c.id !== id);
    setFavorites(updated);
    localStorage.setItem(`favs_${user?.id}`, JSON.stringify(updated));
    window.dispatchEvent(new Event('favoritesUpdated'));
  };

  const tabs = [
    { key: 'profile', label: 'Профиль' },
    { key: 'purchases', label: 'Мои покупки' },
    { key: 'favorites', label: 'Избранное' },
    { key: 'compare', label: 'Сравнение' },
    { key: 'testdrives', label: 'Тест-драйвы' },
    { key: 'loans', label: 'Кредиты' },
    { key: 'notifications', label: `Уведомления (${notifications.length})` },
  ];

  const renderTabContent = () => {
    switch (activeTab) {
      case 'profile':
        return (
          <motion.div className={styles.profileCard} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
            <h3>Личные данные аккаунта</h3>
            <form onSubmit={handleProfileSubmit} className={styles.form}>
              <div className={styles.field}>
                <label>ФИО Пользователя</label>
                <input type="text" value={profileForm.full_name} onChange={e => setProfileForm({ ...profileForm, full_name: e.target.value })} required />
              </div>
              <div className={styles.field}>
                <label>Номер телефона</label>
                <input type="text" value={profileForm.phone} onChange={e => setProfileForm({ ...profileForm, phone: e.target.value })} placeholder="+7 (999) 000-00-00" />
              </div>
              <div className={styles.field}>
                <label>Электронная почта (Email)</label>
                <input type="email" value={user?.email} disabled style={{ opacity: 0.6, cursor: 'not-allowed' }} />
              </div>
              {updateStatus && <p className={updateStatus.type === 'success' ? styles.success : styles.error}>{updateStatus.text}</p>}
              <button type="submit" className={styles.saveBtn}>Сохранить изменения</button>
            </form>
          </motion.div>
        );

      case 'purchases':
        return purchases.length ? (
          <div className={styles.cardsGrid}>
            {purchases.map(p => (
              <div key={p.id} className={styles.receiptCard}>
                <div className={styles.receiptHeader}>
                  <h4>Договор купли-продажи №{p.id}</h4>
                  <span>{new Date(p.created_at).toLocaleDateString('ru-RU')}</span>
                </div>
                <div className={styles.receiptBody}>
                  <div className={styles.receiptRow}><span>Автомобиль:</span> <strong>{p.car_brand} {p.car_model}</strong></div>
                  <div className={styles.receiptRow}><span>Сумма сделки:</span> <strong>{p.price?.toLocaleString()} ₽</strong></div>
                  <div className={styles.receiptRow}><span>Способ оплаты:</span> <span>{p.payment_method === 'cash' ? 'Наличный расчет' : 'Автокредит'}</span></div>
                  <div className={styles.receiptRow}><span>Статус договора:</span> <span className={`${styles.status} ${styles.approved}`}>Оформлен</span></div>
                </div>
                <button className={styles.printBtn} onClick={() => window.print()}>Распечатать чек-ордер</button>
              </div>
            ))}
          </div>
        ) : <p className={styles.empty}>Вы еще не совершали покупок автомобилей.</p>;

      case 'favorites':
        return favorites.length ? (
          <div className={styles.cardsGrid}>
            {favorites.map(car => (
              <div key={car.id} className={styles.carCard}>
                <img src={getImageUrl(car.images?.[0])} alt="" />
                <div className={styles.carInfo}>
                  <h4>{car.brand} {car.model}</h4>
                  <p>{car.price?.toLocaleString()} ₽</p>
                  <div className={styles.cardActions}>
                    <Link to={`/cars/${car.id}`} className={styles.detailLink}>Перейти к авто</Link>
                    <button className={styles.removeBtn} onClick={() => removeFavorite(car.id)}>Удалить</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : <p className={styles.empty}>Список избранного пуст.</p>;

      case 'compare':
        return <ComparePage hideTitle={true} />;

      case 'testdrives':
        return testDrives.length ? (
          <div className={styles.cardsGrid}>
            {testDrives.map(td => (
              <div key={td.id} className={styles.card}>
                <div className={styles.cardHeader}>
                  <h3>Тест-драйв #{td.id}</h3>
                  <span className={`${styles.badge} ${styles[td.status]}`}>{td.status}</span>
                </div>
                <div className={styles.cardBody}>
                  <p><strong>Автомобиль ID:</strong> {td.car_id}</p>
                  <p><strong>Дата встречи:</strong> {new Date(td.date).toLocaleString('ru-RU')}</p>
                  
                  {/* Вывод комментария администратора */}
                  {td.comment && (
                    <div className={styles.managerCommentBox}>
                      <span className={styles.commentLabel}>Комментарий автосалона:</span>
                      <p className={styles.commentText}>{td.comment}</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : <p className={styles.empty}>Записей на тест-драйв пока нет.</p>;

      case 'loans':
        return loans.length ? (
          <div className={styles.cardsGrid}>
            {loans.map(loan => (
              <div key={loan.id} className={styles.card}>
                <div className={styles.cardHeader}>
                  <h3>Кредитная заявка #{loan.id}</h3>
                  <span className={`${styles.badge} ${styles[loan.status]}`}>{loan.status}</span>
                </div>
                <div className={styles.cardBody}>
                  <p><strong>Автомобиль ID:</strong> {loan.car_id}</p>
                  <p><strong>Запрашиваемая сумма:</strong> {loan.amount?.toLocaleString()} ₽</p>
                  <p><strong>Срок кредитования:</strong> {loan.term_months} месяцев</p>
                  <p><strong>Процентная ставка:</strong> {loan.interest_rate}% годовых</p>
                  
                  {/* Вывод комментария администратора / банка */}
                  {loan.comment && (
                    <div className={styles.managerCommentBox}>
                      <span className={styles.commentLabel}>Решение кредитного отдела:</span>
                      <p className={styles.commentText}>{loan.comment}</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : <p className={styles.empty}>Кредитных заявок пока нет.</p>;

      case 'notifications':
        return notifications.length ? (
          <div className={styles.cardsGrid}>
            {notifications.map((n, idx) => (
              <div key={idx} className={`${styles.card} ${styles.notificationCard}`}>
                <div className={styles.cardBody}>{n.message}</div>
              </div>
            ))}
            <button className={styles.clearBtn} onClick={clearNotifications}>Очистить все</button>
          </div>
        ) : <p className={styles.empty}>Нет новых уведомлений.</p>;

      default:
        return null;
    }
  };

  if (loading) return <div className={styles.loading}>Загрузка информации личного кабинета...</div>;

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <h2 className={styles.title}>Личный кабинет – {user.full_name}</h2>
      <div className={styles.tabs}>
        {tabs.map(tab => (
          <button key={tab.key} className={`${styles.tab} ${activeTab === tab.key ? styles.active : ''}`} onClick={() => setActiveTab(tab.key)}>
            {tab.label}
          </button>
        ))}
      </div>
      <div className={styles.content}>
        {renderTabContent()}
      </div>
    </motion.div>
  );
};

export default UserDashboard;
